    throw new Error('user_ids must be non-empty');
  }
  if (userIds.length > MAX_IDS) {
    throw new Error(`user_ids must have at most ${MAX_IDS} entries`);
  }
  // Each entry must be a string
  for (const id of userIds) {
    if (typeof id !== 'string') {
      throw new Error('user_ids must contain only strings');
    }
  }
  // Reject duplicates
  const seen = new Set();
  for (const id of userIds) {
    if (seen.has(id)) {
      throw new Error(`Duplicate user_id: ${id}`);
